// src/pages/Login.js - User Login Page
import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { loginUser } from '../api/authAPI';
import { useAuth } from '../context/AuthContext';

const Login = () => {
  const navigate  = useNavigate();
  const { login } = useAuth();

  // ---- Form State ----
  const [formData, setFormData] = useState({ email: '', password: '' });

  // ---- UI State ----
  const [error,    setError]   = useState('');
  const [success,  setSuccess] = useState('');
  const [loading,  setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);

  // ---- Handle input change ----
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  // ---- Client-side Validation ----
  const validate = () => {
    const { email, password } = formData;
    if (!email.trim() || !password) return 'Please enter your email and password.';
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) return 'Please enter a valid email address.';
    return null;
  };

  // ---- Form Submit ----
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const validationError = validate();
    if (validationError) { setError(validationError); return; }

    setLoading(true);
    try {
      // Call the login API
      const data = await loginUser(formData);

      // Save token and user to global auth context (and localStorage)
      login(data);

      setSuccess('Login successful! Redirecting to dashboard...');

      // Redirect to dashboard
      setTimeout(() => navigate('/dashboard'), 1200);
    } catch (err) {
      const msg = err.response?.data?.message || 'Login failed. Please check your credentials.';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-card">

        {/* ---- Brand Logo ---- */}
        <div className="auth-brand">
          <div className="brand-icon">🔑</div>
          <h1>Welcome Back</h1>
          <p>Sign in to your account to continue</p>
        </div>

        {/* ---- Error Alert ---- */}
        {error && (
          <div className="alert-custom alert-error mb-3">
            <i className="bi bi-exclamation-circle-fill"></i>
            {error}
          </div>
        )}

        {/* ---- Success Alert ---- */}
        {success && (
          <div className="alert-custom alert-success mb-3">
            <i className="bi bi-check-circle-fill"></i>
            {success}
          </div>
        )}

        {/* ---- Login Form ---- */}
        <form onSubmit={handleSubmit} noValidate>

          {/* Email Field */}
          <div className="mb-3">
            <label htmlFor="login-email" className="form-label">Email Address</label>
            <div className="input-group-icon">
              <i className="bi bi-envelope input-icon"></i>
              <input
                id="login-email"
                type="email"
                name="email"
                className="form-control"
                placeholder="john@example.com"
                value={formData.email}
                onChange={handleChange}
                autoComplete="email"
                required
              />
            </div>
          </div>

          {/* Password Field */}
          <div className="mb-4">
            <div className="d-flex justify-content-between align-items-center mb-1">
              <label htmlFor="login-password" className="form-label mb-0">Password</label>
            </div>
            <div className="input-group-icon" style={{ position: 'relative' }}>
              <i className="bi bi-lock input-icon"></i>
              <input
                id="login-password"
                type={showPass ? 'text' : 'password'}
                name="password"
                className="form-control"
                placeholder="Enter your password"
                value={formData.password}
                onChange={handleChange}
                autoComplete="current-password"
                required
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowPass(!showPass)}
                aria-label="Toggle password visibility"
              >
                <i className={`bi ${showPass ? 'bi-eye-slash' : 'bi-eye'}`}></i>
              </button>
            </div>
          </div>

          {/* Submit Button */}
          <button
            id="login-btn"
            type="submit"
            className="btn-auth"
            disabled={loading}
          >
            {loading ? (
              <>
                <span
                  className="spinner-border spinner-border-sm me-2"
                  role="status"
                  aria-hidden="true"
                />
                Signing in...
              </>
            ) : (
              <>
                <i className="bi bi-box-arrow-in-right me-2"></i>
                Sign In
              </>
            )}
          </button>
        </form>

        {/* ---- Divider ---- */}
        <div className="divider">or</div>

        {/* ---- Footer Link ---- */}
        <div className="auth-footer">
          Don't have an account?{' '}
          <Link to="/register" className="auth-link">
            Create one for free
          </Link>
        </div>
      </div>
    </div>
  );
};

export default Login;
